/** Actual future Nether ore/scattered features and native successful removals; no reward/evidence injection. */
final class NetherOreRuntime {
 static void run(GameTestHelper h)throws Exception{
  var over=h.getLevel();var server=over.getServer();var mine=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(mine.owner());h.assertTrue(p!=null,"Original full16Miner owner attends");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var track=store.professions(p.getUUID()).track(Profession.MINER);var data=NetherOreSavedData.get(server);var file=server.getWorldPath(LevelResource.ROOT).resolve("nether-ores-proof.nbt");var nether=server.getLevel(Level.NETHER);
  if(java.nio.file.Files.exists(file)){h.assertTrue(track.xp()==3300&&track.completedQuestIds().size()==19&&ConstructionService.structureIntact(over,mine),"Second JVM restores actual19earned3300XP/original Mine-Doran");for(String id:NetherOres.GOALS.keySet())h.assertTrue(NetherOres.count(p,id)==NetherOres.GOALS.get(id),"Full Nether counters restore");var proof=AtomicNbt.read(file);var retained=BlockPos.of(proof.getLong("retained"));nether.getChunkAt(retained);h.assertTrue(nether.getChunkAt(retained).getData(NetherOres.MARKS).at(retained.asLong())!=null,"Actual unmined generated attachment survives native chunk save");h.assertTrue(!data.evidence().record(UUID.randomUUID(),"minecraft:the_nether",proof.getLong("spent"),"debris"),"Saved spent debris cannot be reused by another player");CommerceService.verifyReceipt(p);server.tickRateManager().setTickRate(20);com.mojang.logging.LogUtils.getLogger().info("NETHER_ORES_RESTART_PASSED: actual64quartz32gold4debris/native generated marks/global spent/19earned3300XP/old16proofs/Mine-Doran/native receipts restored");h.succeed();return;}
  h.assertTrue(track.xp()==2400&&track.completedQuestIds().size()==16&&store.professions(p.getUUID()).progressBand(Profession.MINER)==ProfessionRank.MASTER,"Starts from genuinely earned full16only, no rank proof fixture");var original=NativeOreSavedData.get(server).evidence().save();DimensionTravelRuntimeTests.seed(server,5);p.teleportTo(nether,16*16+.5,100,16*16+.5,Set.of(),0,0);
  var seams=new HashMap<String,List<BlockPos>>();for(String metric:List.of("quartz","nether_gold","debris"))seams.put(metric,new ArrayList<>());for(int x=16;x<20;x++)for(int z=16;z<20;z++){var chunk=nether.getChunk(x,z);var at=new BlockPos(x*16,32,z*16);ClaimRuntimeTests.ftbUnclaim(nether,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacUnclaim(nether,at);ClaimRuntimeTests.opacClaim(nether,p.getUUID(),at);if(chunk.hasData(NetherOres.MARKS))for(long cell:chunk.getData(NetherOres.MARKS).positions()){var pos=BlockPos.of(cell);var block=chunk.getData(NetherOres.MARKS).at(cell);h.assertTrue(net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(nether.getBlockState(pos).getBlock()).toString().equals(block),"Native finished generated state equals attached source");seams.get(NetherOres.BLOCKS.get(block)).add(pos);}}
  h.assertTrue(seams.get("quartz").size()>=70&&seams.get("nether_gold").size()>=33&&seams.get("debris").size()>=6,"Real future Nether generation supplies full approved quantities "+seams.entrySet().stream().map(e->e.getKey()+"="+e.getValue().size()).toList());
  DimensionTravelRuntimeTests.seed(server,4);var low=seams.get("quartz").remove(0);mine(h,p,low,Items.DIAMOND_PICKAXE);h.assertTrue(data.evidence().count(p.getUUID(),"quartz")==0,"Actual native removal at closed Tier4boundary grants no Master credit");DimensionTravelRuntimeTests.seed(server,5);var replaced=seams.get("quartz").remove(0);nether.setBlock(replaced,Blocks.AIR.defaultBlockState(),3);nether.setBlock(replaced,Blocks.NETHER_QUARTZ_ORE.defaultBlockState(),3);mine(h,p,replaced,Items.DIAMOND_PICKAXE);h.assertTrue(data.evidence().count(p.getUUID(),"quartz")==0,"Replaced ore grants drops but no native source proof");var weak=seams.get("debris").remove(0);mine(h,p,weak,Items.IRON_PICKAXE);h.assertTrue(data.evidence().count(p.getUUID(),"debris")==0,"Actual incorrect-tier tool cannot authenticate debris");
  var fault=seams.get("quartz").remove(0);nether.getServer().overworld().getDataStorage().set("kingdomsmp_nether_ores_v1",new net.minecraft.world.level.saveddata.SavedData(){public CompoundTag save(CompoundTag t,HolderLookup.Provider r){return t;}});try{mine(h,p,fault,Items.DIAMOND_PICKAXE);}finally{server.overworld().getDataStorage().set("kingdomsmp_nether_ores_v1",data);data.setDirty();}h.assertTrue(data.evidence().count(p.getUUID(),"quartz")==0&&p.getMainHandItem().getDamageValue()==1,"Bad optional proof cannot escape actual native removal/tool wear");
  var denied=seams.get("nether_gold").get(0);var guard=ClaimRuntimeTests.vanillaPlayer(nether,UUID.nameUUIDFromBytes("NetherOreGuard".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"NetherGuard");guard.teleportTo(nether,denied.getX()+.5,denied.getY()+2,denied.getZ()+.5,Set.of(),0,0);ClaimRuntimeTests.ftbUnclaim(nether,denied);ClaimRuntimeTests.ftbClaim(guard,denied);BlacksmithRepairRuntime.near(p,denied);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_PICKAXE));h.assertTrue(NetherOres.capture(p,denied,true)==null&&!p.gameMode.destroyBlock(denied),"Independent current FTB denial retains rare source");ClaimRuntimeTests.ftbUnclaim(nether,denied);ClaimRuntimeTests.ftbClaim(p,denied);ClaimRuntimeTests.opacUnclaim(nether,denied);ClaimRuntimeTests.opacClaim(nether,guard.getUUID(),denied);h.assertTrue(NetherOres.capture(p,denied,true)==null&&!p.gameMode.destroyBlock(denied),"Independent current OPAC denial preserves source");ClaimRuntimeTests.opacUnclaim(nether,denied);ClaimRuntimeTests.opacClaim(nether,p.getUUID(),denied);long spent=0;for(var row:Map.of("quartz",64,"nether_gold",32,"debris",4).entrySet())for(var at:seams.get(row.getKey()).subList(0,row.getValue())){mine(h,p,at,Items.DIAMOND_PICKAXE);spent=at.asLong();}h.assertTrue(original.equals(NativeOreSavedData.get(server).evidence().save()),"Original Overworld schema2spent/counters/areas are untouched");
  p.teleportTo(over,mine.origin().getX()+.5,mine.origin().getY()+1,mine.origin().getZ()+.5,Set.of(),0,0);CreateCraftRuntime.counter(p,mine);for(String id:NetherOres.GOALS.keySet()){h.assertTrue(NetherOres.count(p,id)==NetherOres.GOALS.get(id),"Actual full quantity native removals only");var quote=ProfessionService.review(p,"quest:"+id);ProfessionService.confirm(p,quote.nonce());boolean replay=false;try{ProfessionService.review(p,"quest:"+id);}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay,"Repeated reward is refused");}h.assertTrue(store.professions(p.getUUID()).track(Profession.MINER).xp()==3300&&store.professions(p.getUUID()).track(Profession.MINER).completedQuestIds().size()==19,"Three genuine300XPawards retain all16original proofs");CommerceService.verifyReceipt(p);var proof=new CompoundTag();proof.putLong("retained",seams.get("quartz").get(65).asLong());proof.putLong("spent",spent);AtomicNbt.write(file,proof);com.mojang.logging.LogUtils.getLogger().info("NETHER_ORES_NATIVE_PASSED: actual future Nether OreFeature+ScatteredOreFeature marks, full64quartz32gold4debris/native correct-tool removals, placed/weak-tool/currentclaim/corrupt-evidence/replay refusals, original Overworld evidence unchanged/19earned3300XP; only private raw tools/native mining-time/Tier5boundary, no source/count/XP/quest/rank injection");h.succeed();
 }
 static void mine(GameTestHelper h,net.minecraft.server.level.ServerPlayer p,BlockPos pos,Item tool){BlacksmithRepairRuntime.near(p,pos);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(tool));h.assertTrue(p.gameMode.destroyBlock(pos),"Actual native permitted Nether extraction succeeds");}
}
